/** [2026-10-29] shared building block for the "agent" filter on list pages.
 *
 * Background: jumping here from an agent card ("sessions / tasks / executions") must narrow the scope to that agent.
 * The approach is not a per-page URL scheme, but:
 *   ① options are generated by de-duplicating the page's own data (whoever has data generates it, no extra fetch)
 *   ② the jumper only carries `?agent=<agentId>`, the page feeds it to DataTable.initialFilterVals
 * So "entered from a card" and "manually selected from the dropdown" use the same filter channel, never two behaviours.
 */

/** de-duplicate { value: agentId, label: agentName } from row data, sorted by name */
export function agentFilterOptions(
  rows: { agentId?: string; agentName?: string }[],
): { label: string; value: string }[] {
  const seen = new Map<string, string>();
  for (const r of rows) {
    const id = r.agentId;
    if (!id || seen.has(id)) continue;
    seen.set(id, r.agentName || id);
  }
  /* Display names may collide (e.g. agx_host / agx_host_srv_a / agx_host_srv_b —
     the agent_name of all three host_manager instances is "agx_host").
     On collision, fall back to agentId as the label — at that point only the id can tell them apart, and showing
     the same name means the user cannot choose. */
  const nameCount = new Map<string, number>();
  for (const n of seen.values()) nameCount.set(n, (nameCount.get(n) ?? 0) + 1);
  return [...seen.entries()]
    .map(([value, name]) => ({ value, label: (nameCount.get(name) ?? 0) > 1 ? value : name }))
    .sort((a, b) => a.label.localeCompare(b.label, "zh-Hans-CN"));
}

/** read ?agent= from the URL and turn it into DataTable's initial filter value (undefined when absent, keep the default) */
export function agentInitialFilter(agentId: string | null): Record<string, string> | undefined {
  return agentId ? { agentId } : undefined;
}

/** targets of the three metric blocks on the agent page: carry the agent param so it lands already filtered */
export function agentScopedLink(
  page: "sessions" | "tasks" | "executions",
  agentId: string,
): string {
  return `/${page}?agent=${encodeURIComponent(agentId)}`;
}
